// Unchanged API67 supplied-key TOTP proof project, independently admitted.
func TestRunAuthTotpSuppliedKeyProof(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAuthTotpKey67.cls"), "@IsTest private class GladeAuthTotpKey67 {\nprivate static String codeAt(Long seconds) {\n Long counter=seconds/30; String digits='0123456789abcdef'; String hex='';\n for(Integer i=0;i<8;i++) { Integer part=Integer.valueOf(String.valueOf(counter-(counter/256)*256)); hex=digits.substring(part/16,part/16+1)+digits.substring(Math.mod(part,16),Math.mod(part,16)+1)+hex; counter=counter/256; }\n String digest=EncodingUtil.convertToHex(Crypto.generateMac('HmacSHA1',EncodingUtil.convertFromHex(hex),Blob.valueOf('12345678901234567890'))).toLowerCase();\n Integer offset=digits.indexOf(digest.substring(digest.length()-1))*2; Long binary=0;\n for(Integer i=offset;i<offset+8;i++) binary=binary*16+digits.indexOf(digest.substring(i,i+1));\n if(binary>=2147483648L) binary-=2147483648L;\n String result=String.valueOf(binary-(binary/1000000)*1000000); while(result.length()<6)result='0'+result; return result;\n}\nprivate static void verifyIndependentVectors() {\n System.assertEquals('287082',codeAt(59L)); System.assertEquals('081804',codeAt(1111111109L)); System.assertEquals('050471',codeAt(1111111111L)); System.assertEquals('005924',codeAt(1234567890L)); System.assertEquals('279037',codeAt(2000000000L)); System.assertEquals('353130',codeAt(20000000000L));\n}\n@IsTest static void acceptsCurrentTwoArgument() { verifyIndependentVectors(); Long now=Datetime.now().getTime()/1000; Boolean result=Auth.SessionManagement.validateTotpTokenForKey('GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ',codeAt(now)); System.assertEquals(true,result); }\n@IsTest static void acceptsCurrentDescribed() { verifyIndependentVectors(); Long now=Datetime.now().getTime()/1000; Boolean result=Auth.SessionManagement.validateTotpTokenForKey('GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ',codeAt(now),'Owned TOTP proof'); System.assertEquals(true,result); }\n@IsTest static void rejectsStaleCode() { verifyIndependentVectors(); Long now=Datetime.now().getTime()/1000; Boolean result=Auth.SessionManagement.validateTotpTokenForKey('GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ',codeAt(now-86400),'Owned stale proof'); System.assertEquals(false,result); }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeAuthTotpKey67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 3 || got.Passed != 3 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact TOTP proof failed: %s", data)
	}
}

